<template><div v-if="pages>1" class="pagination"><button :disabled="page<=1" @click="$emit('change',page-1)">‹</button><button v-for="n in nums" :key="n" :class="{active:n===page}" @click="$emit('change',n)">{{n}}</button><button :disabled="page>=pages" @click="$emit('change',page+1)">›</button></div></template><script setup>import {computed} from 'vue';const p=defineProps({page:Number,pages:Number});defineEmits(['change']);const nums=computed(()=>{let a=[];let s=Math.max(1,p.page-2),e=Math.min(p.pages,s+4);s=Math.max(1,e-4);for(let i=s;i<=e;i++)a.push(i);return a})</script>
